478		mustRegisterCargo(t, r, "G3", 10, "X", true)
479		mustAdjust(t, r, "a0", []Op{
480			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
481			{Kind: OpLoad, CargoID: "G2", Target: "C2"},
482			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
483		})
484	
485		compBefore := snapshotCompartments(r, "C1", "C2")
486		cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
